    let er=d.expense_ratio;if(er!=null&&Number(er)<=1)er=Number(er)*100;$('mf-expense').textContent=er==null?'--':`${num(er)}%`;$('mf-benchmark').textContent=b.name||'--';$('mf-fund-cagr').textContent=pct(b.fund_cagr_pct);$('mf-bench-cagr').textContent=pct(b.benchmark_cagr_pct);$('mf-alpha').textContent=pct(b.alpha_vs_benchmark_pct);$('mf-tracking').textContent=pct(b.tracking_error_pct);$('mf-correlation').textContent=num(b.correlation,3);$('mf-beta').textContent=num(b.beta);$('mf-aligned-sessions').textContent=b.aligned_sessions??'--';$('mf-aum').textContent=compact(d.total_assets);
    $('mf-detail-house').textContent=d.fund_house||'--';$('mf-type').textContent=d.scheme_type||d.quote_type||'--';$('mf-detail-category').textContent=d.scheme_category||'--';$('mf-cost-status').textContent=profile.cost_status||'--';$('mf-benchmark-status').textContent=profile.benchmark_status||'--';$('mf-current-drawdown').textContent=pct(profile.current_drawdown_pct);$('mf-risk-band').textContent=profile.risk_band||'--';$('mf-consistency-status').textContent=`Consistency ${profile.consistency_status||'--'}`;
    const rolling=profile.rolling_returns||{};$('mf-rolling-range').innerHTML=`<div class="mini-kpi"><span>Median rolling 1Y</span><b>${pct(rolling.median_1y_pct)}</b></div><div class="mini-kpi"><span>Best rolling 1Y</span><b>${pct(rolling.best_1y_pct)}</b></div><div class="mini-kpi"><span>Worst rolling 1Y</span><b>${pct(rolling.worst_1y_pct)}</b></div>`;$('mf-profile-reasons').innerHTML=(profile.reasons||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join('')||'<li>No additional profile notes available.</li>';$('mf-profile-note').textContent=profile.note||'';
    const horizons=['1D','1M','3M','6M','1Y','3Y','5Y'];$('mf-return-timeframes').innerHTML=horizons.map(label=>{const v=r[label],tone=v==null?'NEUTRAL':v>=0?'BULLISH':'BEARISH';return `<button class="timeframe-bias-card ${label===selectedFundHorizon?'active':''}" data-fund-horizon="${label}"><span class="timeframe-label">${label}</span><strong class="${tone.toLowerCase()}">${pct(v)}</strong><small>${label==='3Y'||label==='5Y'?'annualized':'historical'}</small></button>`}).join('');$('mf-return-timeframes').querySelectorAll('.timeframe-bias-card').forEach(card=>card.addEventListener('click',()=>showFundHorizon(card.dataset.fundHorizon)));showFundHorizon(selectedFundHorizon);
