    drawFundNavChart(d);drawFundBenchmarkChart(d);const keys=['1D','1M','3M','6M','1Y','3Y','5Y'];if(mfReturnsChart)mfReturnsChart.destroy();mfReturnsChart=new Chart($('mf-returns-chart'),{type:'bar',data:{labels:keys,datasets:[{label:'Return %',data:keys.map(k=>r[k]??0)}]},options:{responsive:true,plugins:{legend:{display:false}}}});
